package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class StdDateFormat_parseAsISO8601_TriageGen0Test {

    private StdDateFormat stdDateFormat;
    private TimeZone utc;

    @Before
    public void setUp() {
        utc = TimeZone.getTimeZone("UTC");
        stdDateFormat = new StdDateFormat(utc, Locale.ENGLISH);
    }

    /**
     * Helper to bypass protected access for testing.
     * Since the target method is protected, we use a subclass or 
     * rely on the fact that StdDateFormat's public parse() calls it.
     * However, to test the specific logic of parseAsISO8601 with ParsePosition,
     * we use the public parse(String, ParsePosition) method which delegates to it.
     */
    private Date parse(String dateStr, ParsePosition pos) {
        return stdDateFormat.parse(dateStr, pos);
    }

    @Test
    public void testParsePlainDate() throws Exception {
        // len <= 10 && Character.isDigit(c)
        String dateStr = "2023-10-01";
        Date result = parse(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(2023, cal.get(Calendar.YEAR));
        assertEquals(Calendar.OCTOBER, cal.get(Calendar.MONTH));
        assertEquals(1, cal.get(Calendar.DAY_OF_MONTH));
    }

    @Test
    public void testParseZuluWithMissingMilliseconds() throws Exception {
        // c == 'Z' and dateStr.charAt(len-4) == ':'
        // Tests the sb.insert(len-1, ".000") logic
        String dateStr = "2023-10-01T12:00:00Z";
        Date result = parse(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(12, cal.get(Calendar.HOUR_OF_DAY));
        assertEquals(0, cal.get(Calendar.MINUTE));
        assertEquals(0, cal.get(Calendar.SECOND));
    }

    @Test
    public void testParseZuluWithMilliseconds() throws Exception {
        // c == 'Z' but no colon at len-4
        String dateStr = "2023-10-01T12:00:00.123Z";
        Date result = parse(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(12, cal.get(Calendar.HOUR_OF_DAY));
        assertEquals(123, cal.get(Calendar.MILLISECOND));
    }

    @Test
    public void testParseWithTimeZoneOffsetAndColon() throws Exception {
        // hasTimeZone(dateStr) is true, c == ':' at len-3
        // Tests sb.delete(len-3, len-2)
        String dateStr = "2023-10-01T12:00:00+05:00";
        Date result = parse(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        // 12:00 +05:00 is 07:00 UTC
        assertEquals(7, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParseWithTimeZoneOffsetMissingMinutes() throws Exception {
        // hasTimeZone(dateStr) is true, c == '+' or '-' at len-3
        // Tests dateStr += "00"
        String dateStr = "2023-10-01T12:00:00+05";
        Date result = parse(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(7, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParseWithTimeZoneOffsetAndMissingMilliseconds() throws Exception {
        // hasTimeZone(dateStr) is true, c is digit at len-9
        // Tests sb.insert(len-5, ".000")
        // Format: 2023-10-01T12:00:00+0500 (len 25, len-9 is '0' at index 16)
        String dateStr = "2023-10-01T12:00:00+0500";
        Date result = parse(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(7, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParseWithoutTimeZoneIndicator() throws Exception {
        // hasTimeZone(dateStr) is false
        // Tests appending ".000" and "Z"
        String dateStr = "2023-10-01T12:00:00";
        Date result = parse(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        // Since it appends Z, it should be treated as UTC
        assertEquals(12, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParsePlainDateWithShortTime() throws Exception {
        // len <= 10 and ends with digit
        String dateStr = "20231001";
        Date result = parse(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(2023, cal.get(Calendar.YEAR));
    }

    @Test
    public void testParseWithAlreadyIncludedMillisecondsAndNoZ() throws Exception {
        // hasTimeZone is false, but timeLen is not <= 8
        // This tests the branch where we don't append .000 because it's already there
        String dateStr = "2023-10-01T12:00:00.123";
        Date result = parse(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance(utc);
        cal.setTime(result);
        assertEquals(12, cal.get(Calendar.HOUR_OF_DAY));
        assertEquals(123, cal.get(Calendar.MILLISECOND));
    }
}
